BEGIN;
CREATE TEMP TABLE proj_loc_evidence(label text,data jsonb);
DO $test$
DECLARE r record; planner uuid; principal uuid; director uuid; non_director uuid; architect uuid; pid uuid; missing uuid; c record; v jsonb; allowed boolean; editable boolean; pending integer;
BEGIN
 SELECT user_id INTO planner FROM public.user_roles WHERE role='planning_head' LIMIT 1;
 SELECT user_id INTO principal FROM public.user_roles WHERE role='principal_architect' LIMIT 1;
 SELECT user_id INTO director FROM public.user_roles WHERE role='managing_director' LIMIT 1;
 SELECT user_id INTO non_director FROM public.user_roles WHERE role='head_of_projects' LIMIT 1;
 IF planner IS NULL OR principal IS NULL OR director IS NULL THEN RAISE EXCEPTION 'Required account absent'; END IF;
 SELECT id INTO architect FROM public.profiles WHERE auth_user_id=principal AND is_active;
 IF public.is_tier1_or_super(planner) THEN RAISE EXCEPTION 'Creator must be non-director'; END IF;
 SELECT count(*) INTO pending FROM public.approval_requests;
 IF to_regprocedure('public.raise_project_request(jsonb,text,text)') IS NOT NULL OR to_regprocedure('public.get_project_request_client_contact(uuid)') IS NOT NULL THEN RAISE EXCEPTION 'Retired staging RPC remains'; END IF;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prosrc ILIKE '%project_client_contact_requests%') THEN RAISE EXCEPTION 'Staging function reference remains'; END IF;
 PERFORM set_config('request.jwt.claim.sub',director::text,true); SET LOCAL ROLE authenticated;
 PERFORM public.grant_project_creator(planner,'Rollback-only contact cleanup check');
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',planner::text,true); SET LOCAL ROLE authenticated;
 pid:=public.create_project(jsonb_build_object('name','PROJ-LOC cleanup rollback','client_name','Validation client','project_architect_id',architect,'division','ADS','production_system','hybrid','module_count',2,'panel_count',3,'start_date','2026-11-22','est_completion','2027-01-22','location','Bengaluru','site_lat',12.9716,'site_lng',77.5946,'site_radius',300),'9876543210','proj-loc@example.invalid');
 IF EXISTS(SELECT 1 FROM public.get_project_client_contact(pid)) THEN RAISE EXCEPTION 'Granted creator read'; END IF;
 BEGIN PERFORM client_phone FROM public.projects WHERE id=pid; RAISE EXCEPTION 'Creator direct contact read'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',non_director::text,true); SET LOCAL ROLE authenticated;
 IF EXISTS(SELECT 1 FROM public.get_project_client_contact(pid)) THEN RAISE EXCEPTION 'Non-director reader'; END IF;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',director::text,true); SET LOCAL ROLE authenticated;
 SELECT * INTO c FROM public.get_project_client_contact(pid);
 IF c.client_phone IS DISTINCT FROM '+919876543210' OR c.client_email IS DISTINCT FROM 'proj-loc@example.invalid' THEN RAISE EXCEPTION 'Director contact read'; END IF;
 RESET ROLE;
 IF EXISTS(SELECT 1 FROM public.project_client_contact_requests) THEN RAISE EXCEPTION 'Retired store received contact'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.projects WHERE id=pid AND client_phone='+919876543210' AND client_email='proj-loc@example.invalid') THEN RAISE EXCEPTION 'Direct storage failed'; END IF;
 IF (SELECT count(*) FROM public.approval_requests)<>pending OR EXISTS(SELECT 1 FROM public.approval_requests WHERE payload::text ~ '(9876543210|proj-loc@example.invalid)') THEN RAISE EXCEPTION 'Approval payload leak'; END IF;
 IF EXISTS(SELECT 1 FROM public.admin_audit_log WHERE entity_id=pid AND to_jsonb(admin_audit_log)::text ~ '(9876543210|proj-loc@example.invalid)') OR EXISTS(SELECT 1 FROM public.project_location_contact_log WHERE project_id=pid AND to_jsonb(project_location_contact_log)::text ~ '(9876543210|proj-loc@example.invalid)') OR EXISTS(SELECT 1 FROM public.super_admin_audit_log WHERE entity=pid::text AND to_jsonb(super_admin_audit_log)::text ~ '(9876543210|proj-loc@example.invalid)') OR EXISTS(SELECT 1 FROM public.notifications WHERE related_id=pid AND to_jsonb(notifications)::text ~ '(9876543210|proj-loc@example.invalid)') THEN RAISE EXCEPTION 'Audit/notification leak'; END IF;
 INSERT INTO proj_loc_evidence VALUES('direct_creation','{"granted_non_director_created":true,"payload_private":true,"creator_denied":true,"director_read":true,"staging_empty":true,"audit_notifications_private":true}');
 FOR r IN SELECT ur.user_id,array_agg(ur.role::text ORDER BY ur.role::text) roles FROM public.user_roles ur JOIN public.profiles pr ON pr.auth_user_id=ur.user_id WHERE pr.is_active GROUP BY ur.user_id LOOP
  PERFORM set_config('request.jwt.claim.sub',r.user_id::text,true); SET LOCAL ROLE authenticated;
  allowed:=r.roles && ARRAY['managing_director','finance_director','sales_director','architecture_director','super_admin']; editable:=allowed OR r.roles && ARRAY['head_of_projects'];
  SELECT * INTO c FROM public.get_project_client_contact(pid);
  IF (c.client_phone IS NOT NULL) IS DISTINCT FROM allowed THEN RAISE EXCEPTION 'Contact role %',r.roles; END IF;
  IF allowed THEN PERFORM public.set_project_client_contact(pid,'9876543210','proj-loc@example.invalid'); ELSE BEGIN PERFORM public.set_project_client_contact(pid,'9876543210','proj-loc@example.invalid'); RAISE EXCEPTION 'Contact edit %',r.roles; EXCEPTION WHEN insufficient_privilege THEN NULL; END; END IF;
  IF editable THEN PERFORM public.set_project_site_location(pid,'Bengaluru',12.9716,77.5946,300); ELSE BEGIN PERFORM public.set_project_site_location(pid,'Bengaluru',12.9716,77.5946,300); RAISE EXCEPTION 'Location edit %',r.roles; EXCEPTION WHEN insufficient_privilege THEN NULL; END; END IF;
  BEGIN PERFORM client_phone FROM public.projects WHERE id=pid; RAISE EXCEPTION 'Direct column read'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  RESET ROLE;
  INSERT INTO proj_loc_evidence VALUES('role',jsonb_build_object('roles',r.roles,'contact',allowed,'location',editable));
 END LOOP;
 PERFORM set_config('request.jwt.claim.sub','',true); SET LOCAL ROLE anon;
 BEGIN PERFORM public.get_project_client_contact(pid); RAISE EXCEPTION 'Anonymous contact'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.set_project_site_location(pid,'Site',12,77,300); RAISE EXCEPTION 'Anonymous location'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 RESET ROLE;
 INSERT INTO proj_loc_evidence VALUES('anonymous','{"contact_denied":true,"location_denied":true}');
 PERFORM set_config('request.jwt.claim.sub',director::text,true);
 INSERT INTO public.projects(name,status,created_by,updated_by) VALUES('PROJ-LOC missing pin','Active',director,director) RETURNING id INTO missing;
 SET LOCAL ROLE authenticated;
 BEGIN PERFORM public.save_labour_attendance(missing,public.ist_today(),'[]'::jsonb,NULL); RAISE EXCEPTION 'Missing-pin labour accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Site location is not set. Ask a director or the Head of Projects to set it.' THEN RAISE; END IF; END;
 BEGIN INSERT INTO public.attendance_records(user_id,date,location_type,project_id,gps_lat,gps_lng) VALUES(director,'2025-01-01','site',missing,12.9716,77.5946); RAISE EXCEPTION 'Missing-pin check-in accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Site location is not set. Ask a director or the Head of Projects to set it.' THEN RAISE; END IF; END;
 BEGIN PERFORM public.save_labour_attendance(pid,public.ist_today(),'[]'::jsonb,NULL); RAISE EXCEPTION 'No-photo accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Take the toolbox talk photo first.' THEN RAISE; END IF; END;
 RESET ROLE;
 INSERT INTO proj_loc_evidence VALUES('attendance','{"missing_pin_labour_blocked":true,"missing_pin_employee_blocked":true,"configured_photo_gate_unchanged":true}');
 SET LOCAL ROLE authenticated;
 v:=public.get_running_bill('e4f51cd6-fb25-475e-980a-5e46070d678f','2026-11-22');
 IF (v->'totals'->>'value_earned')::numeric<>151000 OR (v->'totals'->>'own_labour_cost')::numeric<>6365.46 OR (v->'totals'->>'subcontract_accrued')::numeric<>0 OR (v->'totals'->>'excess_value')::numeric<>19500 THEN RAISE EXCEPTION 'Running Bill regression'; END IF;
 RESET ROLE;
 INSERT INTO proj_loc_evidence VALUES('running_bill',v->'totals');
 IF (SELECT count(*) FROM public.reminder_events)<>0 THEN RAISE EXCEPTION 'Reminder events changed'; END IF;
END $test$;
SELECT jsonb_agg(jsonb_build_object('label',label,'data',data)) evidence FROM proj_loc_evidence;
ROLLBACK;